// Package oapi connects the server generated by oapi-codegen (strict server
// over net/http) and the kin-openapi validator with the house envelope.
//
// Contract-first flow: contracts/openapi.yaml is the source of truth →
// `go generate ./...` produces the ServerInterface → StrictServerInterface is
// implemented → this package translates what the validator rejects and what
// the handlers return into the envelope {success:false, error, fields}.
//
//	spec, _ := gen.GetSpec()
//	validator := oapi.Validator(spec, oapi.ValidatorOptions{Auth: authenticate})
//	strict := gen.NewStrictHandlerWithOptions(srv, nil, oapi.StrictOptions())
//	gen.HandlerWithOptions(strict, gen.StdHTTPServerOptions{
//	    BaseRouter: mux, Middlewares: []gen.MiddlewareFunc{validator},
//	    ErrorHandlerFunc: oapi.RequestErrorHandler,
//	})
//
// A strict handler can return response.NotFound("...") and
// ResponseErrorHandler answers it with its status and code; there is no need
// to build the generated error response types.
package oapi

import (
	"context"
	"errors"
	"net/http"
	"regexp"
	"strings"

	"github.com/getkin/kin-openapi/openapi3"
	"github.com/getkin/kin-openapi/openapi3filter"
	nethttpmiddleware "github.com/oapi-codegen/nethttp-middleware"

	"github.com/g-studio-labs/gokit/response"
)

// ValidatorOptions tunes Validator.
type ValidatorOptions struct {
	// Auth validates the contract's security schemes (cookie, bearer, apiKey).
	// Returning an error responds 401.
	Auth openapi3filter.AuthenticationFunc
	// ExcludeBody skips body validation (large uploads).
	ExcludeBody bool
}

// Validator is the kin-openapi middleware for the contract's routes: it
// validates parameters, body and security, and reports all invalid fields at
// once with the house envelope.
func Validator(spec *openapi3.T, o ValidatorOptions) func(http.Handler) http.Handler {
	return nethttpmiddleware.OapiRequestValidatorWithOptions(spec, &nethttpmiddleware.Options{
		Options: openapi3filter.Options{
			MultiError:         true,
			AuthenticationFunc: o.Auth,
			ExcludeRequestBody: o.ExcludeBody,
		},
		ErrorHandlerWithOpts: ValidationErrorHandler,
	})
}

// StrictOptions are the strict handler options with this package's handlers.
// If the project does not use Validator, the strict server still responds
// with the envelope.
func StrictOptions() struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
} {
	return struct {
		RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
		ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
	}{RequestErrorHandler, ResponseErrorHandler}
}

// ValidationErrorHandler translates what kin-openapi rejected (parameters,
// body or security) into the envelope. It goes in Validator as ErrorHandlerWithOpts.
func ValidationErrorHandler(_ context.Context, err error, w http.ResponseWriter, r *http.Request, _ nethttpmiddleware.ErrorHandlerOpts) {
	if _, ok := errors.AsType[*openapi3filter.SecurityRequirementsError](err); ok {
		response.Fail(w, r, response.Unauthorized("").Wrap(err))
		return
	}
	response.Fail(w, r, response.Validation(Fields(err)...))
}

// RequestErrorHandler covers what the generated router could not parse (rare:
// the validator runs first). It serves as ErrorHandlerFunc and
// RequestErrorHandlerFunc.
func RequestErrorHandler(w http.ResponseWriter, r *http.Request, err error) {
	field := "request"
	if m := reParam.FindStringSubmatch(err.Error()); m != nil {
		field = m[1]
	}
	response.Fail(w, r, response.Validation(response.FieldError{Field: field, Message: "formato no válido", Rule: "format"}).Wrap(err))
}

var reParam = regexp.MustCompile(`parameter "?([A-Za-z0-9_.-]+)"?`)

// ResponseErrorHandler is the strict server's ResponseErrorHandlerFunc: a
// handler returned an error. A *response.Error reaches the client with its
// status and code; anything else is 500 (logged with cause, generic message).
func ResponseErrorHandler(w http.ResponseWriter, r *http.Request, err error) {
	response.Fail(w, r, err)
}

var reMissing = regexp.MustCompile(`property "([^"]+)" is (?:missing|unsupported)`)

// Fields flattens kin-openapi errors to {field, message}. They come nested
// (MultiError → RequestError → MultiError → SchemaError), so they are walked
// by exact type, level by level: errors.As would jump to the inner MultiError
// and lose which parameter it was.
//
// The message is always SchemaError.Reason, which does not include the received
// value: err.Error() does, and on a login it would be the password.
func Fields(err error) []response.FieldError {
	switch e := err.(type) {
	case openapi3.MultiError:
		var out []response.FieldError
		for _, x := range e {
			out = append(out, Fields(x)...)
		}
		return out
	case *openapi3filter.RequestError:
		schemas := schemaErrors(e.Err)
		if e.Parameter != nil {
			msg := e.Reason
			if len(schemas) > 0 {
				msg = schemas[0].Reason
			}
			return []response.FieldError{{Field: e.Parameter.Name, Message: orGeneric(msg), Rule: "schema"}}
		}
		if len(schemas) == 0 {
			return []response.FieldError{{Field: "body", Message: orGeneric(e.Reason), Rule: "schema"}}
		}
		out := make([]response.FieldError, 0, len(schemas))
		for _, se := range schemas {
			out = append(out, fieldOf(se))
		}
		return out
	case *openapi3.SchemaError:
		return []response.FieldError{fieldOf(e)}
	default:
		return []response.FieldError{{Field: "request", Message: "petición no válida", Rule: "schema"}}
	}
}

func schemaErrors(err error) []*openapi3.SchemaError {
	switch e := err.(type) {
	case *openapi3.SchemaError:
		return []*openapi3.SchemaError{e}
	case openapi3.MultiError:
		var out []*openapi3.SchemaError
		for _, x := range e {
			out = append(out, schemaErrors(x)...)
		}
		return out
	}
	return nil
}

// fieldOf: the JSON path of the value ("password", "details.origin"). If the
// error is about an object missing or having an extra property, the property
// is named.
func fieldOf(se *openapi3.SchemaError) response.FieldError {
	field := strings.Join(se.JSONPointer(), ".")
	if field == "" {
		if m := reMissing.FindStringSubmatch(se.Reason); m != nil {
			field = m[1]
		}
	}
	if field == "" {
		field = "body"
	}
	rule := se.SchemaField
	if rule == "" {
		rule = "schema"
	}
	return response.FieldError{Field: field, Message: orGeneric(se.Reason), Rule: rule}
}

func orGeneric(m string) string {
	if m == "" {
		return "valor no válido"
	}
	return m
}
